func PriceOrder(lines []Line, discountBP int64, taxBP int64) int64 {
	var taxableSubtotal int64
	var nonTaxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		// Calculate line total in cents
		lineTotal := line.Price * line.Qty

		// Apply discount and round the result of each line individually
		// Formula: (lineTotal * (10000 - discountBP) + 5000) / 10000
		numerator := lineTotal * (10000 - discountBP)
		roundedLineTotal := (numerator + 5000) / 10000

		if line.Taxable {
			taxableSubtotal += roundedLineTotal
		} else {
			nonTaxableSubtotal += roundedLineTotal
		}
	}

	// Compute tax from the DISCOUNTED taxable subtotal, rounded once
	// Formula: (taxableSubtotal * taxBP + 5000) / 10000
	taxNumerator := taxableSubtotal * taxBP
	taxAmount := (taxNumerator + 5000) / 10000

	// Total = Sum of all discounted/rounded lines + rounded tax
	return taxableSubtotal + nonTaxableSubtotal + taxAmount
}
```

