func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var discountedTotal int64
	var taxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		// Calculate line total in cents: Price * Qty
		lineTotal := line.Price * line.Qty

		// Apply discount and round each line: (numerator + 5000) / 10000
		// numerator = lineTotal * (10000 - discountBP)
		numerator := lineTotal * (10000 - discountBP)
		roundedLineTotal := (numerator + 5000) / 10000

		discountedTotal += roundedLineTotal

		if line.Taxable {
			// The taxable subtotal is the sum of the already discounted/rounded line totals for taxable items
			taxableSubtotal += roundedLineTotal
		}
	}

	// Compute tax from the DISCOUNTED taxable subtotal
	// Tax = (taxableSubtotal * taxBP + 5000) / 10000
	taxNumerator := taxableSubtotal * taxBP
	taxAmount := (taxNumerator + 5000) / 10000

	return discountedTotal + taxAmount
}
